import{_ as s,c as e,o,ag as n}from"./chunks/framework.Cycwnjj0.js";const r="/assets/other-settings-option-from-azonpress-dashboard.C3Tcl8-T.webp",i="/assets/othe-settings-popup-page.D6WDcL1V.webp",m=JSON.parse('{"title":"Other Settings in AzonPress","description":"","frontmatter":{},"headers":[],"relativePath":"guide/miscellaneous/other-settings.md","filePath":"guide/miscellaneous/other-settings.md"}'),a={name:"guide/miscellaneous/other-settings.md"};function l(g,t,h,c,d,u){return o(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="other-settings-in-azonpress" tabindex="-1">Other Settings in AzonPress <a class="header-anchor" href="#other-settings-in-azonpress" aria-label="Permalink to &quot;Other Settings in AzonPress&quot;">​</a></h1><p>In AzonPress, the &quot;Other Settings&quot; feature allows you to <strong>Assign</strong> the <strong>Users</strong> full <strong>Admin Access</strong> for a specific <strong>AzonPress Site/Plugin</strong>. Also, you can decide with this setting option whether you want to load the CSS and JS file globally or on-demand. This article will guide you through giving admin access to the users.</p><h2 id="give-admin-access-to-users-with-other-settings" tabindex="-1">Give Admin Access to Users with Other Settings <a class="header-anchor" href="#give-admin-access-to-users-with-other-settings" aria-label="Permalink to &quot;Give Admin Access to Users with Other Settings&quot;">​</a></h2><p>To learn how you can <strong>give</strong> your <strong>AzonPress Site&#39;s</strong> full <strong>Admin Access</strong> to the <strong>Users</strong> of your <strong>WordPress Site</strong>, follow the steps with the screenshots below –</p><p>First, go to <strong>Settings</strong> from the <strong>AzonPress Navbar</strong> and click on <strong>Other Settings.</strong></p><p><img src="'+r+'" alt="Other Settings option from AzonPress dashboard"></p><p>Now, here you can see, two major settings options. These are:</p><ul><li><strong>Global Asset Loading</strong></li><li><strong>AzonPress Access Roles</strong></li></ul><p><strong>Global Asset Loading</strong>: Here, you can see, by default the &quot;Load CSS and JS On-Demand&quot; option is enabled to load the CSS and JS files based on scopes. But if you want to load all CSS and JS files globally, you can simply enable the &quot;Load CSS and JS Globally&quot; option.</p><p><strong>AzonPress Access Roles:</strong> Now, here you will get all the roles for giving the admin access. To do this, just simply click the checkbox of your desired user role/s, and that specific user/s will get all the admin access to your AzonPress site.</p><p>Once you are done, click the <strong>Update</strong> button to save all the changes.</p><p><img src="'+i+'" alt="Other Settings Popup page"></p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',14)])])}const S=s(a,[["render",l]]);export{m as __pageData,S as default};
